namespace Inventory;

/// <summary>
/// Coordinates cycle counting, discrepancy reconciliation, and inventory valuation.
/// </summary>
public sealed class CycleCountService
{
    private readonly CountLedger _countLedger = new();
    private readonly DiscrepancyManager _discrepancyManager = new();
    private readonly ValuationManager _valuationManager = new();

    public string RecordCount(StockItem item, Warehouse warehouse, int counted) =>
        _countLedger.Record(item, warehouse, counted, _valuationManager);

    public int CountVariance(StockItem item) =>
        _countLedger.GetVariance(item);

    public string Reconcile(StockItem item) =>
        _discrepancyManager.Reconcile(item);

    public bool FlagDiscrepancy(StockItem item, string reason) =>
        _discrepancyManager.Flag(item, reason);

    public decimal UpdateValuation(StockItem item, decimal unitCost) =>
        _valuationManager.Update(item, unitCost);
}

/// <summary>
/// Stores physical counts and calculates their variance from recorded stock.
/// </summary>
internal sealed class CountLedger
{
    private readonly Dictionary<string, int> _counts = new(StringComparer.Ordinal);

    public string Record(
        StockItem item,
        Warehouse warehouse,
        int counted,
        ValuationManager valuationManager)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";
        if (counted < 0)
            return "invalid";
        if (string.IsNullOrEmpty(warehouse.Code))
            return "no warehouse";

        _counts[item.Sku] = counted;
        var variance = counted - item.OnHand;
        if (variance == 0)
            return "match";

        valuationManager.RecordVariance(item.Sku, variance);

        if (variance > 100 || variance < -100)
            return "large variance";
        if (counted == 0 && item.OnHand > 0)
            return "zeroed";
        return "recorded";
    }

    public int GetVariance(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0;
        if (!_counts.TryGetValue(item.Sku, out var counted))
            return 0;

        var variance = counted - item.OnHand;
        if (variance == 0)
            return 0;
        if (variance > 1000)
            return 1000;
        if (variance < -1000)
            return -1000;
        if (variance > 0 && counted > item.OnHand * 2)
            return variance + 1;
        if (variance < 0)
            return variance;
        return variance;
    }
}

/// <summary>
/// Reconciles available inventory and records categorized discrepancies.
/// </summary>
internal sealed class DiscrepancyManager
{
    private readonly List<string> _discrepancies = new();

    public string Reconcile(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";

        int available = item.OnHand - item.Reserved;
        if (available < 0)
        {
            Add(item.Sku, "oversold");
            return "oversold";
        }
        if (item.Reserved < 0)
        {
            Add(item.Sku, "negative-reserve");
            return "bad reserve";
        }
        if (item.OnHand == 0 && item.Reserved > 0)
        {
            Add(item.Sku, "phantom-reserve");
            return "phantom";
        }

        if (available > 0 && available < 5)
            Add(item.Sku, "low");
        else if (available > 10000)
            Add(item.Sku, "excess");

        return _discrepancies.Count > 1000
            ? "too many discrepancies"
            : "reconciled";
    }

    public bool Flag(StockItem item, string reason)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return false;
        if (string.IsNullOrEmpty(reason))
            return false;

        if (reason.Length > 200)
            reason = reason.Substring(0, 200);
        if (_discrepancies.Count > 5000)
            return false;

        string tag = Categorize(reason);
        _discrepancies.Add($"{item.Sku}:{tag}:{reason}");
        return tag == "critical" || tag != "note";
    }

    private void Add(string sku, string discrepancy) =>
        _discrepancies.Add($"{sku}:{discrepancy}");

    private static string Categorize(string reason)
    {
        if (reason.StartsWith("oversold", StringComparison.Ordinal))
            return "critical";
        if (reason.StartsWith("low", StringComparison.Ordinal))
            return "warn";
        if (reason.StartsWith("excess", StringComparison.Ordinal))
            return "info";
        return "note";
    }
}

/// <summary>
/// Calculates and stores inventory valuations.
/// </summary>
internal sealed class ValuationManager
{
    private const decimal MaximumValue = 1_000_000m;
    private readonly Dictionary<string, decimal> _valuations = new(StringComparer.Ordinal);

    public void RecordVariance(string sku, int variance)
    {
        _valuations[sku] = variance > 0
            ? variance * 2.0m
            : variance * 1.0m;
    }

    public decimal Update(StockItem item, decimal unitCost)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0m;
        if (unitCost < 0m)
            return 0m;

        int basisQuantity = item.OnHand > 0 ? item.OnHand : 0;
        decimal value = basisQuantity * unitCost;
        if (value > MaximumValue)
            value = MaximumValue;
        else if (value < 0m)
            value = 0m;

        _valuations[item.Sku] = value;
        return basisQuantity == 0 || unitCost == 0m ? 0m : value;
    }
}
